// File or memory access pattern advisory information.
type Advice uint8

const (
	// The application has no advice to give on its behavior with respect
	// to the specified data.
	AdviceNormal Advice = 0
	// The application expects to access the specified data sequentially
	// from lower offsets to higher offsets.
	AdviceSequential Advice = 1
	// The application expects to access the specified data in a random
	// order.
	AdviceRandom Advice = 2
	// The application expects to access the specified data in the near
	// future.
	AdviceWillNeed Advice = 3
	// The application expects that it will not access the specified data
	// in the near future.
	AdviceDontNeed Advice = 4
	// The application expects to access the specified data once and then
	// not reuse it thereafter.
	AdviceNoReuse Advice = 5
)

func (v Advice) String() string {
	switch v {
	case AdviceNormal:
		return "normal"
	case AdviceSequential:
		return "sequential"
	case AdviceRandom:
		return "random"
	case AdviceWillNeed:
		return "will-need"
	case AdviceDontNeed:
		return "dont-need"
	case AdviceNoReuse:
		return "no-reuse"
	}
	return "Advice(unknown)"
}

// Descriptor flags.
//
// Note: This was called `fdflags` in earlier versions of WASI.
type DescriptorFlags uint32

const (
	// Read mode: Data can be read.
	DescriptorFlagsRead DescriptorFlags = 1 << 0
	// Write mode: Data can be written to.
	DescriptorFlagsWrite DescriptorFlags = 1 << 1
	// Request that writes be performed according to synchronized I/O file
	// integrity completion. The data stored in the file and the file's
	// metadata are synchronized. This is similar to `O_SYNC` in POSIX.
	//
	// The precise semantics of this operation have not yet been defined for
	// WASI. At this time, it should be interpreted as a request, and not a
	// requirement.
	DescriptorFlagsFileIntegritySync DescriptorFlags = 1 << 2
	// Request that writes be performed according to synchronized I/O data
	// integrity completion. Only the data stored in the file is
	// synchronized. This is similar to `O_DSYNC` in POSIX.
	//
	// The precise semantics of this operation have not yet been defined for
	// WASI. At this time, it should be interpreted as a request, and not a
	// requirement.
	DescriptorFlagsDataIntegritySync DescriptorFlags = 1 << 3
	// Requests that reads be performed at the same level of integrity
	// requested for writes. This is similar to `O_RSYNC` in POSIX.
	//
	// The precise semantics of this operation have not yet been defined for
	// WASI. At this time, it should be interpreted as a request, and not a
	// requirement.
	DescriptorFlagsRequestedWriteSync DescriptorFlags = 1 << 4
	// Mutating directories mode: Directory contents may be mutated.
	//
	// When this flag is unset on a descriptor, operations using the
	// descriptor which would create, rename, delete, modify the data or
	// metadata of filesystem objects, or obtain another handle which
	// would permit any of those, shall fail with `error-code::read-only` if
	// they would otherwise succeed.
	//
	// This may only be set on directories.
	DescriptorFlagsMutateDirectory DescriptorFlags = 1 << 5
)

// Flags determining the method of how paths are resolved.
type PathFlags uint32

const (
	// As long as the resolved path corresponds to a symbolic link, it is
	// expanded.
	PathFlagsSymlinkFollow PathFlags = 1 << 0
)

// Open flags used by `open-at`.
type OpenFlags uint32

const (
	// Create file if it does not exist, similar to `O_CREAT` in POSIX.
	OpenFlagsCreate OpenFlags = 1 << 0
	// Fail if not a directory, similar to `O_DIRECTORY` in POSIX.
	OpenFlagsDirectory OpenFlags = 1 << 1
	// Fail if file already exists, similar to `O_EXCL` in POSIX.
	OpenFlagsExclusive OpenFlags = 1 << 2
	// Truncate file to size 0, similar to `O_TRUNC` in POSIX.
	OpenFlagsTruncate OpenFlags = 1 << 3
)

